import { Command, CommandHelpInfo, RawInteraction } from '../../core/Command.js';

/**
 * Simple ping command - demonstrates basic command structure
 */
export class PingCommand extends Command {
  public readonly data = {
    name: 'ping',
    description: 'Check if the bot is responding',
    type: 1, // CHAT_INPUT
  };

  public readonly helpInfo: CommandHelpInfo = {
    name: 'ping',
    description: 'Check if the bot is responding and get latency information',
    usage: '/ping',
    examples: ['/ping'],
    category: 'Utility',
  };

  public async execute(
    interaction: RawInteraction,
    env: Record<string, unknown>,
    rest: { post: (url: string, options: { body: unknown }) => Promise<unknown> }
  ): Promise<void> {
    const startTime = Date.now();

    // Send initial reply
    await rest.post(`/interactions/${interaction.id}/${interaction.token}/callback`, {
      body: {
        type: 4, // CHANNEL_MESSAGE_WITH_SOURCE
        data: {
          content: 'Pinging...',
        },
      },
    });

    // Calculate latency
    const latency = Date.now() - startTime;
    const token = env.DISCORD_TOKEN as string;
    const applicationId = interaction.application_id;

    // Edit reply with latency info
    await fetch(
      `https://discord.com/api/v10/webhooks/${applicationId}/${interaction.token}/messages/@original`,
      {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bot ${token}`,
        },
        body: JSON.stringify({
          content: `🏓 **Pong!**\n📡 **Latency:** ${latency}ms\n💓 **API Latency:** ~${latency}ms`,
        }),
      }
    );
  }
}
