import { RawInteraction } from '../../core/Command.js';

/**
 * User subcommand for info command
 */
export class InfoUserSubcommand {
  public async execute(
    interaction: RawInteraction,
    env: Record<string, unknown>,
    rest: { post: (url: string, options: { body: unknown }) => Promise<unknown> }
  ): Promise<void> {
    // Get target user option
    const userSubcommand = interaction.data?.options?.find((opt) => opt.name === 'user');
    const targetOption = (
      userSubcommand as { options?: Array<{ name: string; value: unknown }> }
    )?.options?.find((opt) => opt.name === 'target');
    const targetUserId = (targetOption?.value as string) || interaction.user?.id || '';

    // Use interaction user as fallback
    const user = interaction.user || interaction.member?.user;
    if (!user) {
      await rest.post(`/interactions/${interaction.id}/${interaction.token}/callback`, {
        body: {
          type: 4,
          data: {
            content: '❌ Unable to get user information.',
            flags: 64,
          },
        },
      });
      return;
    }

    const username = user.username || 'Unknown';
    const discriminator = user.discriminator || '0';
    const tag = `${username}${discriminator !== '0' ? `#${discriminator}` : ''}`;
    const displayName = user.global_name || username;

    // Calculate created timestamp from user ID (snowflake)
    const userId = user.id;
    const createdTimestamp = Number(BigInt(userId) >> 22n) + 1420070400000;

    // Fetch user details from Discord API if we have a target user ID
    let userDetails: { bot?: boolean; avatar?: string | null } = {};
    if (targetUserId && targetUserId !== userId) {
      const token = env.DISCORD_TOKEN as string;
      try {
        const userResponse = await fetch(`https://discord.com/api/v10/users/${targetUserId}`, {
          headers: {
            Authorization: `Bot ${token}`,
          },
        });
        if (userResponse.ok) {
          userDetails = (await userResponse.json()) as { bot?: boolean; avatar?: string | null };
        }
      } catch {
        // Ignore errors
      }
    }

    const embed = {
      title: `👤 User Information`,
      description: `Information about ${tag}`,
      color: 0x00ae86,
      thumbnail: {
        url: `https://cdn.discordapp.com/avatars/${userId}/${userDetails.avatar || 'default'}.png`,
      },
      fields: [
        {
          name: '📊 Basic Info',
          value: [
            `**Username:** ${username}`,
            `**Display Name:** ${displayName}`,
            `**ID:** ${userId}`,
            `**Bot:** ${userDetails.bot ? 'Yes' : 'No'}`,
          ].join('\n'),
          inline: true,
        },
        {
          name: '📅 Dates',
          value: [
            `**Account Created:** <t:${Math.floor(createdTimestamp / 1000)}:F>`,
            `**Joined Server:** ${interaction.member?.joined_at ? `<t:${Math.floor(Date.parse(interaction.member.joined_at) / 1000)}:F>` : 'Not in server'}`,
          ].join('\n'),
          inline: true,
        },
      ],
      timestamp: new Date().toISOString(),
    };

    await rest.post(`/interactions/${interaction.id}/${interaction.token}/callback`, {
      body: {
        type: 4,
        data: {
          embeds: [embed],
        },
      },
    });
  }
}
