/**
 * Utilities for building Discord interaction responses
 */
export class InteractionResponse {
  /**
   * Create a PONG response (for verification)
   */
  public static pong(): Response {
    return new Response(JSON.stringify({ type: 1 }), {
      headers: { 'Content-Type': 'application/json' },
    });
  }

  /**
   * Create an error response
   */
  public static error(message: string, ephemeral: boolean = true): Response {
    return new Response(
      JSON.stringify({
        type: 4,
        data: {
          content: `❌ ${message}`,
          flags: ephemeral ? 64 : 0,
        },
      }),
      {
        headers: { 'Content-Type': 'application/json' },
      }
    );
  }

  /**
   * Create a deferred response (for long-running operations)
   */
  public static deferred(ephemeral: boolean = false): Response {
    return new Response(
      JSON.stringify({
        type: 5,
        data: {
          flags: ephemeral ? 64 : 0,
        },
      }),
      {
        headers: { 'Content-Type': 'application/json' },
      }
    );
  }

  /**
   * Create a channel message response
   */
  public static message(content: string, ephemeral: boolean = false): Response {
    return new Response(
      JSON.stringify({
        type: 4,
        data: {
          content,
          flags: ephemeral ? 64 : 0,
        },
      }),
      {
        headers: { 'Content-Type': 'application/json' },
      }
    );
  }
}
